import React, { useContext } from 'react'
import './fooditem.css'
import { assets } from '../fassets/assets'
import { StoreContext } from '../context/StoreContext'
const FoodItem = ({id,name,price,description,image}) => {


    

    let{cartItems, setCartItems, addtoCart, removeCart}=useContext(StoreContext);

  return (
    <div className='food-item'>
      <div className='food-item-img-container'>
              <img className='food-item-image ' src={image} alt=''/>
               {
                          !cartItems[id]?<img className='add' onClick={()=>addtoCart(id)} src={assets.add_icon_white} alt=''/>
                            :<div className='food-item-count'>
                                <img   onClick={()=>removeCart(id)} src={assets.remove_icon_red} alt=''/>
                                <p>{cartItems[id]}</p>
                                <img onClick={()=>addtoCart(id)} src={assets.add_icon_green} alt=''/>
                            </div>
                           }
      </div>

      <div className='food-item-info'>
        <div className='food-item-name-rating'>
             
               <p>{name}</p>
                <img src={assets.rating_starts}alt=''/>
                <p className='food-item-desc'>{description}</p>
               <p className='food-item-price'>&#8377;{price}</p>
        </div>

      </div>
    

    </div>

    
    
  )
}

export default FoodItem
